  const alongX = x1 - x0 >= z1 - z0;
  const length = alongX ? x1 - x0 : z1 - z0;
  for (let t = 0.3; t < length - 0.1; t += 0.42) {
    if (alongX) batch.box(x0 + t - 0.08, 0.1, z0 - 0.05, x0 + t + 0.08, r.height - 0.1, z1 + 0.05, dark, 8);
