      if (known && bomb.state !== 'defused' && bomb.state !== 'exploded') {
        const at = bomb.carrier ? bomb.carrier.body : bomb;
        g.fillStyle = bomb.state === 'planted' ? '#ff3b2f' : PALETTE.lamp;
