  return {
    update(dt, viewer) {
      for (const m of models) {
        const a = m.actor;
        const b = a.body;
        const visible = a !== viewer;
        m.root.visible = visible;
        if (!visible) continue;
        m.root.position.set(b.x, b.y, b.z);
        m.root.rotation.y = b.yaw;
        m.pack.visible = a.hasBomb;
        m.tag.visible = a.alive && viewer !== null && a.team === viewer.team;
        if (!a.alive) {
